// Synthetic, reproducible datasets (seeded). Free to use: generated by Python Quest, no real people.
// They intentionally contain the problems analysts meet in practice: missing values,
// duplicates, inconsistent labels, outliers and skew.
import { rng } from "../stats/math";

const r2 = (v: number) => Math.round(v * 100) / 100;

function toCsv(header: string[], rows: (string | number | null)[][]) {
  return [header.join(","), ...rows.map((r) => r.map((v) => (v === null ? "" : String(v))).join(","))].join("\n") + "\n";
}

export function ventasCsv(): string {
  const r = rng(2024);
  const regiones = ["Norte", "Sur", "Este", "Oeste"];
  const productos: [string, number][] = [
    ["Pociones", 12.5],
    ["Espadas", 85],
    ["Mapas", 20],
    ["Escudos", 60],
  ];
  const rows: (string | number | null)[][] = [];
  let id = 1000;
  for (let d = 0; d < 120; d++) {
    const date = new Date(Date.UTC(2025, 0, 1 + d));
    const iso = date.toISOString().slice(0, 10);
    const n = 2 + r.int(0, 2);
    for (let i = 0; i < n; i++) {
      const [prod, price] = productos[r.int(0, 3)];
      let region: string = regiones[r.int(0, 3)];
      if (r.next() < 0.03) region = region.toLowerCase() + " "; // inconsistent label
      const weekend = date.getUTCDay() === 0 || date.getUTCDay() === 6;
      const units = Math.max(1, Math.round(r.normal(weekend ? 9 : 6, 2.5)));
      const unitsCell: number | null = r.next() < 0.04 ? null : units;
      rows.push([id++, iso, region, prod, unitsCell, price]);
      if (r.next() < 0.02) rows.push([...rows[rows.length - 1]]); // duplicate row
    }
  }
  rows.push([id++, "2025-03-15", "Sur", "Espadas", 140, 85]); // outlier
  return toCsv(["pedido", "fecha", "region", "producto", "unidades", "precio"], rows);
}

export function pacientesCsv(): string {
  const r = rng(77);
  const rows: (string | number | null)[][] = [];
  for (let i = 1; i <= 160; i++) {
    const grupo = i % 2 ? "control" : "tratamiento";
    const edad = Math.round(Math.min(85, Math.max(25, r.normal(56, 11))));
    const sexo = r.next() < 0.52 ? "F" : "M";
    const fumador = r.next() < 0.28 ? 1 : 0;
    const pas0 = r2(r.normal(148 + 0.25 * (edad - 56) + 4 * fumador, 12));
    const efecto = grupo === "tratamiento" ? -9 : -2;
    const pas1 = r2(pas0 + efecto + r.normal(0, 8));
    const evento = r.next() < (grupo === "tratamiento" ? 0.12 : 0.22) + 0.05 * fumador ? 1 : 0;
    rows.push([i, grupo, edad, sexo, fumador, pas0, r.next() < 0.03 ? null : pas1, evento]);
  }
  return toCsv(["id", "grupo", "edad", "sexo", "fumador", "pas_inicial", "pas_final", "evento"], rows);
}

export function estudiantesCsv(): string {
  const r = rng(5150);
  const rows: (string | number)[][] = [];
  for (let i = 1; i <= 200; i++) {
    const horas = r2(Math.max(0, r.normal(6, 3)));
    const asistencia = r2(Math.min(1, Math.max(0.3, r.normal(0.82, 0.12))));
    const previa = r2(Math.min(10, Math.max(0, r.normal(6, 1.6))));
    const nota = r2(Math.min(10, Math.max(0, 1 + 0.35 * horas + 3 * asistencia + 0.35 * previa + r.normal(0, 1.1))));
    rows.push([i, horas, asistencia, previa, nota, nota >= 5 ? 1 : 0]);
  }
  return toCsv(["id", "horas_estudio", "asistencia", "nota_previa", "nota_final", "aprobado"], rows);
}

export function climaCsv(): string {
  const r = rng(31);
  const rows: (string | number)[][] = [];
  for (let d = 0; d < 365; d++) {
    const date = new Date(Date.UTC(2025, 0, 1 + d)).toISOString().slice(0, 10);
    const temp = r2(14 + 9 * Math.sin(((d - 100) / 365) * 2 * Math.PI) + r.normal(0, 2.2));
    const lluvia = r.next() < 0.3 ? r2(r.exponential(1 / 6)) : 0;
    rows.push([date, temp, lluvia]);
  }
  return toCsv(["fecha", "temperatura", "lluvia_mm"], rows);
}

export function clientesCsv(): string {
  const r = rng(909);
  const contratos = ["mensual", "anual", "bianual"];
  const rows: (string | number | null)[][] = [];
  for (let i = 1; i <= 1200; i++) {
    const contrato = contratos[r.next() < 0.55 ? 0 : r.next() < 0.6 ? 1 : 2];
    const antiguedad = Math.max(1, Math.round(contrato === "mensual" ? r.exponential(1 / 14) : r.normal(36, 14)));
    const cuota = r2(Math.max(15, r.normal(contrato === "mensual" ? 72 : 60, 18)));
    const llamadas = r.poisson(contrato === "mensual" ? 2.2 : 1.2);
    const fibra = r.next() < 0.45 ? 1 : 0;
    const z = -2.6 + (contrato === "mensual" ? 1.6 : contrato === "anual" ? 0.2 : -0.6) - 0.035 * antiguedad + 0.018 * (cuota - 60) + 0.38 * llamadas + 0.35 * fibra;
    const baja = r.next() < 1 / (1 + Math.exp(-z)) ? 1 : 0;
    rows.push([i, contrato, antiguedad, cuota, llamadas, fibra, r.next() < 0.02 ? null : r2(cuota * antiguedad), baja]);
  }
  return toCsv(["cliente", "contrato", "antiguedad_meses", "cuota_mensual", "llamadas_soporte", "fibra", "gasto_total", "baja"], rows);
}

/** Two-arm cholesterol trial: randomised in blocks, with dropouts and data-entry problems. */
export function ensayoCsv(): string {
  const r = rng(4242);
  const rows: (string | number | null)[][] = [];
  const centros = ["A", "B", "C"];
  let id = 1;
  for (let bloque = 0; bloque < 60; bloque++) {
    // Permuted blocks of 4 (2 + 2) keep the arms balanced over time.
    const brazos = ["placebo", "placebo", "farmaco", "farmaco"];
    for (let i = 3; i > 0; i--) {
      const j = r.int(0, i);
      [brazos[i], brazos[j]] = [brazos[j], brazos[i]];
    }
    for (const brazo of brazos) {
      const centro = centros[r.int(0, 2)];
      const edad = Math.round(Math.min(80, Math.max(35, r.normal(58, 9))));
      const mujer = r.next() < 0.47;
      const imc = r2(Math.max(18, r.normal(28, 4)));
      const basal = Math.round(r.normal(165 + 0.3 * (edad - 58) + (centro === "C" ? 6 : 0), 22));
      const efecto = brazo === "farmaco" ? -24 : -6;
      const final = Math.round(basal + efecto + 0.1 * (imc - 28) + r.normal(0, 21));
      // Dropout more likely with side effects (more frequent with the drug) and in centre B.
      const adverso = r.next() < (brazo === "farmaco" ? 0.16 : 0.07) ? 1 : 0;
      const abandono = r.next() < 0.05 + 0.25 * adverso + (centro === "B" ? 0.04 : 0);
      const sexo = mujer ? (r.next() < 0.06 ? "f" : "F") : r.next() < 0.06 ? "m" : "M";
      // Typing errors in the age of two patients.
      const edadCelda = id === 17 ? 999 : id === 133 ? -1 : edad;
      rows.push([id, centro, brazo, edadCelda, sexo, imc, basal, abandono ? null : final, adverso]);
      if (r.next() < 0.012 || id === 58) rows.push([...rows[rows.length - 1]]); // duplicated row
      id++;
    }
  }
  return toCsv(["id", "centro", "brazo", "edad", "sexo", "imc", "ldl_basal", "ldl_12s", "evento_adverso"], rows);
}

/** Hourly temperature of two sensors for 60 days with injected anomalies (labels in sensoresEtiquetasCsv). */
function sensoresData() {
  const r = rng(1312);
  type Row = { t: number; sensor: string; v: number | string | null; anom: number };
  const out: Row[] = [];
  const start = Date.UTC(2025, 2, 1);
  for (const [sensor, base, amp] of [["S1", 21, 3], ["S2", 18, 5]] as [string, number, number][]) {
    let stuck = 0;
    let stuckVal = 0;
    for (let h = 0; h < 60 * 24; h++) {
      const hour = h % 24;
      let v = base + amp * Math.sin(((hour - 9) / 24) * 2 * Math.PI) + r.normal(0, 0.6) + 0.01 * (h / 24);
      let anom = 0;
      if (stuck > 0) {
        v = stuckVal;
        stuck--;
        anom = 1;
      } else if (r.next() < 0.004) {
        v += (r.next() < 0.5 ? -1 : 1) * (6 + 6 * r.next()); // spike
        anom = 1;
      } else if (r.next() < 0.0015) {
        stuck = 5 + r.int(0, 6); // stuck sensor: repeats a value for several hours
        stuckVal = r2(v);
      } else if (r.next() < 0.004 && (hour < 5 || hour > 21)) {
        v += 5.5 + 2 * r.next(); // contextual: normal by day, abnormal at night
        anom = 1;
      }
      out.push({ t: start + h * 3600_000, sensor, v: r2(v), anom });
    }
  }
  return { out, r };
}

export function sensoresCsv(): string {
  const { out, r } = sensoresData();
  const rows: (string | number | null)[][] = [];
  for (const row of out) {
    const u = r.next();
    if (u < 0.01) continue; // lost reading
    const iso = new Date(row.t).toISOString().slice(0, 16).replace("T", " ");
    rows.push([iso, row.sensor, u < 0.016 ? "ERR" : row.v]);
    if (u > 0.995) rows.push([iso, row.sensor, row.v]); // duplicated message
  }
  // Messages arrive out of order: swap some neighbours.
  for (let i = 1; i < rows.length; i++) if (r.next() < 0.02) [rows[i - 1], rows[i]] = [rows[i], rows[i - 1]];
  return toCsv(["fecha_hora", "sensor", "temperatura"], rows);
}

export function sensoresEtiquetasCsv(): string {
  const { out } = sensoresData();
  return toCsv(
    ["fecha_hora", "sensor", "anomalia"],
    out.map((row) => [new Date(row.t).toISOString().slice(0, 16).replace("T", " "), row.sensor, row.anom]),
  );
}

/** Housing prices with a skewed target, neighbourhood effects, missing values and a few typos. */
export function viviendasCsv(): string {
  const r = rng(808);
  const barrios: [string, number, number][] = [
    ["Centro", 1.55, 1.2],
    ["Ensanche", 1.3, 2.8],
    ["Universidad", 1.05, 3.5],
    ["Puerto", 0.95, 5],
    ["Afueras", 0.7, 9],
  ];
  const rows: (string | number | null)[][] = [];
  for (let i = 1; i <= 1500; i++) {
    const [barrio, factor, dist] = barrios[Math.min(4, Math.floor(r.next() * 5))];
    const superficie = Math.round(Math.max(28, r.normal(barrio === "Afueras" ? 105 : 82, 28)));
    const habitaciones = Math.max(1, Math.min(6, Math.round(superficie / 30 + r.normal(0, 0.6))));
    const banos = Math.max(1, Math.min(3, Math.round(superficie / 60 + r.normal(0, 0.4))));
    const antiguedad = Math.max(0, Math.round(barrio === "Centro" ? r.normal(70, 25) : r.normal(30, 18)));
    const planta = r.int(0, 9);
    const ascensor = planta === 0 ? (r.next() < 0.5 ? 1 : 0) : r.next() < (antiguedad > 50 ? 0.45 : 0.9) ? 1 : 0;
    const distancia = r2(Math.max(0.2, r.normal(dist, dist * 0.25)));
    const sinAscensorAlto = !ascensor && planta >= 3 ? -0.12 : 0;
    const logPrecio = Math.log(2.6 * superficie * factor) - 0.004 * antiguedad + 0.035 * banos + 0.012 * planta + sinAscensorAlto - 0.015 * distancia + r.normal(0, 0.13);
    const precio = Math.round(Math.exp(logPrecio));
    let sup: number = superficie;
    if (r.next() < 0.004) sup = superficie * 10; // typed an extra zero
    rows.push([i, barrio, sup, habitaciones, banos, r.next() < 0.05 ? null : antiguedad, planta, ascensor, distancia, precio]);
  }
  return toCsv(["id", "barrio", "superficie_m2", "habitaciones", "banos", "antiguedad", "planta", "ascensor", "distancia_centro_km", "precio_miles"], rows);
}

/** Customer messages for text classification (Spanish, no commas so the CSV needs no quoting). */
export function mensajesCsv(): string {
  const r = rng(2718);
  const plantillas: Record<string, string[]> = {
    facturacion: [
      "me han cobrado dos veces el mismo pedido",
      "la factura tiene un importe incorrecto",
      "necesito la factura con mis datos fiscales",
      "no reconozco un cargo en mi tarjeta",
      "el precio cobrado no coincide con el anunciado",
      "quiero un duplicado de la factura",
      "me cobraron gastos de envío que no correspondían",
      "el reembolso no aparece en mi cuenta bancaria",
      "el descuento no se aplicó al pagar",
    ],
    envio: [
      "mi pedido no ha llegado todavía",
      "el paquete lleva una semana en reparto",
      "el repartidor dejó el paquete en otra dirección",
      "quiero cambiar la dirección de entrega",
      "el seguimiento del envío no se actualiza",
      "¿cuándo llegará mi pedido?",
      "el envío llegó con mucho retraso",
      "el transportista no pasó a la hora acordada",
      "me dicen que el paquete fue entregado pero no lo tengo",
    ],
    defecto: [
      "el producto llegó roto",
      "la espada vino doblada y no sirve",
      "el mapa tiene páginas rotas",
      "la poción estaba abierta y derramada",
      "el escudo tiene una grieta enorme",
      "quiero devolver un artículo defectuoso",
      "el producto no funciona desde el primer día",
      "faltan piezas en la caja del pedido",
    ],
    cuenta: [
      "no puedo iniciar sesión en mi cuenta",
      "olvidé mi contraseña y no puedo entrar",
      "quiero cambiar el correo de mi cuenta",
      "me han bloqueado la cuenta sin motivo",
      "quiero borrar mi cuenta y mis datos personales",
      "no me llega el correo de verificación",
    ],
  };
  const pesos: [string, number][] = [["envio", 0.35], ["facturacion", 0.3], ["defecto", 0.22], ["cuenta", 0.13]];
  const saludos = ["hola", "buenos días", "buenas tardes", "", "", "por favor ayuda", "urgente"];
  const despedidas = ["gracias", "un saludo", "espero respuesta pronto", "", "", "es la segunda vez que escribo", "estoy muy molesto"];
  const categorias = Object.keys(plantillas);
  const sinonimos: Record<string, string[]> = {
    pedido: ["pedido", "compra", "encargo"],
    paquete: ["paquete", "bulto"],
    roto: ["roto", "dañado", "estropeado"],
    cobrado: ["cobrado", "cargado"],
    factura: ["factura", "fra"],
    llegado: ["llegado", "aparecido"],
    correo: ["correo", "email", "e-mail"],
    contraseña: ["contraseña", "clave"],
  };
  const pistas: Record<string, string[]> = {
    facturacion: ["el pago", "el cobro", "la factura"],
    envio: ["la entrega", "el reparto", "el envío"],
    defecto: ["el artículo", "lo que compré", "el producto"],
    cuenta: ["mi usuario", "el acceso", "mi perfil"],
  };
  const rows: (string | number)[][] = [];
  for (let i = 1; i <= 900; i++) {
    let u = r.next();
    let cat = pesos[pesos.length - 1][0];
    for (const [c, w] of pesos) {
      if (u < w) {
        cat = c;
        break;
      }
      u -= w;
    }
    const frases = plantillas[cat];
    const v = r.next();
    let cuerpo: string;
    if (v < 0.12) {
      // Vague message: the category is only hinted at by one word.
      cuerpo = `tengo un problema con ${pistas[cat][r.int(0, pistas[cat].length - 1)]}`;
    } else {
      let palabras = frases[r.int(0, frases.length - 1)].split(" ").map((w) => {
        const alt = sinonimos[w];
        return alt && r.next() < 0.5 ? alt[r.int(0, alt.length - 1)] : w;
      });
      if (r.next() < 0.15 && palabras.length > 4) palabras.splice(r.int(1, palabras.length - 2), 1); // a dropped word
      if (r.next() < 0.3) palabras.push("pedido", String(r.int(1000, 9999)));
      cuerpo = palabras.join(" ");
      if (v > 0.82) {
        // Two topics in one message; the label is the main (first) one.
        const otra = categorias.filter((c) => c !== cat)[r.int(0, 2)];
        cuerpo += ` y además ${plantillas[otra][r.int(0, plantillas[otra].length - 1)]}`;
      }
    }
    let texto = [saludos[r.int(0, saludos.length - 1)], cuerpo, despedidas[r.int(0, despedidas.length - 1)]].filter(Boolean).join(". ");
    if (r.next() < 0.2) texto = texto.toUpperCase();
    else texto = texto.charAt(0).toUpperCase() + texto.slice(1);
    if (r.next() < 0.15) texto += "!!!";
    // 3 % of labels are wrong, as in real annotated data.
    const etiqueta = r.next() < 0.03 ? categorias[r.int(0, categorias.length - 1)] : cat;
    rows.push([i, texto, etiqueta]);
  }
  return toCsv(["id", "texto", "categoria"], rows);
}

/** Daily electricity demand (MWh) for three years: trend, weekly and yearly cycles, temperature, holidays. */
export const FESTIVOS = ["01-01", "01-06", "05-01", "08-15", "10-12", "11-01", "12-06", "12-08", "12-25"];

export function demandaCsv(): string {
  const r = rng(6020);
  const rows: (string | number | null)[][] = [];
  const inicio = Date.UTC(2022, 0, 1);
  const dias = 3 * 365 + 1; // 2022-2024 (2024 is a leap year)
  let ruido = 0;
  for (let d = 0; d < dias; d++) {
    const fecha = new Date(inicio + d * 86_400_000);
    const iso = fecha.toISOString().slice(0, 10);
    const diaAnio = Math.floor((Date.UTC(fecha.getUTCFullYear(), fecha.getUTCMonth(), fecha.getUTCDate()) - Date.UTC(fecha.getUTCFullYear(), 0, 1)) / 86_400_000);
    const temp = 15 + 9 * Math.sin(((diaAnio - 110) / 365) * 2 * Math.PI) + r.normal(0, 2.5);
    const semana = fecha.getUTCDay(); // 0 = domingo
    const festivo = FESTIVOS.includes(iso.slice(5));
    let demanda = 620 + 0.06 * d; // slow growth
    demanda += semana === 0 ? -95 : semana === 6 ? -60 : 0;
    demanda += 0.9 * (temp - 17) ** 2; // heating and cooling: U-shaped in temperature
    if (festivo) demanda -= 85;
    ruido = 0.5 * ruido + r.normal(0, 14); // autocorrelated noise
    demanda += ruido;
    const falta = r.next() < 0.008;
    rows.push([iso, falta ? null : Math.round(demanda * 10) / 10, Math.round(temp * 10) / 10]);
  }
  return toCsv(["fecha", "demanda_mwh", "temperatura"], rows);
}

/** Spanish bank-statement style: «;» separator, dd/mm/yyyy dates and amounts like «-1.234,56». */
function importeEs(v: number): string {
  const [ent, dec] = Math.abs(v).toFixed(2).split(".");
  const miles = ent.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return `${v < 0 ? "-" : ""}${miles},${dec}`;
}

export function gastosCsv(): string {
  const r = rng(3103);
  const filas: { t: number; concepto: string; importe: number }[] = [];
  const dia = (mes: number, d: number) => Date.UTC(2024, mes, d);
  const add = (t: number, concepto: string, importe: number) => filas.push({ t, concepto, importe: Math.round(importe * 100) / 100 });
  const comercios: [string, string[], number, number][] = [
    ["super", ["MERCADONA 2341", "CARREFOUR EXPRESS 118", "LIDL 0457", "mercadona  2341"], 42, 18],
    ["restaurante", ["BAR LA PLAZA", "RESTAURANTE EL OLIVO", "GLOVO*PEDIDO 8812"], 24, 9],
    ["transporte", ["GASOLINERA REPSOL 22", "TAXI FREENOW"], 38, 12],
    ["compras", ["AMAZON MKTPLACE", "ZARA 0331", "DECATHLON 104"], 35, 20],
  ];
  const veces = [9, 4, 3, 2];
  for (let mes = 0; mes < 12; mes++) {
    add(dia(mes, 1), "RECIBO ALQUILER PISO", -650);
    add(dia(mes, 3), "MOVISTAR FIBRA", -45.9);
    add(dia(mes, 5), "NETFLIX.COM", -12.99);
    add(dia(mes, 12), "SPOTIFY P1A2B3", -10.99);
    if (mes < 7) add(dia(mes, 8), "GIMNASIO FITNESS PARK", -39.9);
    if (mes >= 8) add(dia(mes, 20), "APP PREMIUM STUDIO", -4.99);
    add(dia(mes, 2), "METRO RECARGA TARJETA", -20);
    if (mes % 2 === 1) add(dia(mes, 14), "RECIBO IBERDROLA LUZ", -(62 + 30 * Math.abs(Math.cos((mes / 12) * 2 * Math.PI)) + r.normal(0, 4)));
    if (mes % 3 === 2) add(dia(mes, 18), "RECIBO CANAL AGUA", -(31 + r.normal(0, 3)));
    add(dia(mes, 27), "TRANSF NOMINA EMPRESA SL", mes === 5 || mes === 11 ? 3700 : 1850);
    comercios.forEach(([, nombres, media, sd], k) => {
      const n = veces[k] + r.int(0, 2);
      for (let i = 0; i < n; i++) {
        const d = 1 + r.int(0, 27);
        add(dia(mes, d), nombres[r.int(0, nombres.length - 1)], -Math.max(3, r.normal(media, sd)));
      }
    });
  }
  add(dia(10, 24), "MEDIAMARKT 0021", -899);
  add(dia(3, 9), "AMAZON DEVOLUCION", 35.5);
  add(dia(7, 16), "BIZUM DE LAURA", 25);
  filas.sort((a, b) => a.t - b.t);
  const rows: string[] = [];
  for (const f of filas) {
    const d = new Date(f.t);
    const fecha = `${String(d.getUTCDate()).padStart(2, "0")}/${String(d.getUTCMonth() + 1).padStart(2, "0")}/${d.getUTCFullYear()}`;
    const linea = `${fecha};${f.concepto};${importeEs(f.importe)}`;
    rows.push(linea);
    if (r.next() < 0.015) rows.push(linea); // exported twice by the bank
  }
  return ["fecha;concepto;importe", ...rows].join("\n") + "\n";
}

const GENEROS = ["drama", "comedia", "ciencia ficción", "terror", "animación", "documental"];

/** Invented films and ratings from a latent-factor model with a long tail of popularity. */
function cineData() {
  const r = rng(4242);
  const inicios = ["El faro", "La ciudad", "El último viaje", "La sombra", "El jardín", "La voz", "El reino", "La noche", "El secreto", "La isla", "El tren", "La carta"];
  const finales = ["del norte", "de cristal", "sin nombre", "de los lobos", "en la niebla", "de papel", "del olvido", "bajo la lluvia", "de medianoche", "sin final"];
  const peliculas: { id: number; titulo: string; genero: number; anio: number; q: number[]; b: number; pop: number }[] = [];
  const usados = new Set<string>();
  for (let i = 0; peliculas.length < 120; i++) {
    const titulo = `${inicios[r.int(0, inicios.length - 1)]} ${finales[r.int(0, finales.length - 1)]}`;
    if (usados.has(titulo)) {
      if (i > 5000) break;
      continue;
    }
    usados.add(titulo);
    const genero = peliculas.length % GENEROS.length;
    const q = GENEROS.map((_, g) => (g === genero ? 1 : 0) + r.normal(0, 0.25));
    peliculas.push({ id: 101 + peliculas.length, titulo, genero, anio: 1985 + r.int(0, 39), q, b: r.normal(0, 0.35), pop: 1 / Math.pow(1 + r.int(0, 119), 0.9) });
  }
  const filas: (string | number)[][] = [];
  const inicio = Date.UTC(2023, 0, 1);
  for (let u = 1; u <= 300; u++) {
    const gustos = GENEROS.map(() => r.normal(0, 0.35));
    gustos[r.int(0, GENEROS.length - 1)] += 1.1;
    gustos[r.int(0, GENEROS.length - 1)] += 0.6;
    const bu = r.normal(0, 0.3);
    const afinidad = peliculas.map((m) => m.q.reduce((acc, v, g) => acc + v * gustos[g], 0));
    const pesos = peliculas.map((m, i) => m.pop * Math.exp(1.2 * afinidad[i]));
    const n = Math.min(70, 12 + Math.floor(r.exponential(1 / 18)));
    const vistos = new Set<number>();
    while (vistos.size < n) {
      let x = r.next() * pesos.reduce((a, b) => a + b, 0);
      let i = 0;
      while (x > pesos[i] && i < pesos.length - 1) x -= pesos[i++];
      vistos.add(i);
    }
    for (const i of vistos) {
      const m = peliculas[i];
      const nota = Math.min(5, Math.max(1, Math.round(3.3 + bu + m.b + 0.9 * afinidad[i] + r.normal(0, 0.6))));
      const fecha = new Date(inicio + r.int(0, 729) * 86_400_000).toISOString().slice(0, 10);
      filas.push([u, m.id, nota, fecha]);
    }
  }
  return { peliculas, filas };
}

export function peliculasCsv(): string {
  return toCsv(["pelicula", "titulo", "genero", "anio"], cineData().peliculas.map((m) => [m.id, m.titulo, GENEROS[m.genero], m.anio]));
}

export function valoracionesCsv(): string {
  return toCsv(["usuario", "pelicula", "nota", "fecha"], cineData().filas);
}

/** Forest inventory: height grows as a power of diameter, with a different law per species. */
export function arbolesCsv(): string {
  const r = rng(8086);
  const especies: [string, number, number, number, number][] = [
    // nombre, ln(a), exponente b, ln(diámetro) medio, desviación
    ["pino", 0.15, 0.78, Math.log(18), 0.35],
    ["roble", 0.65, 0.55, Math.log(32), 0.35],
    ["haya", 0.35, 0.68, Math.log(42), 0.3],
  ];
  const rows: (string | number | null)[][] = [];
  let id = 1;
  for (const [nombre, la, b, lmu, lsd] of especies) {
    for (let k = 0; k < 100; k++) {
      const d = Math.exp(r.normal(lmu, lsd));
      const h = Math.exp(la + b * Math.log(d) + r.normal(0, 0.12));
      const edad = Math.round(Math.max(5, 2.2 * d + r.normal(0, 8)));
      rows.push([id++, `P${1 + r.int(0, 9)}`, nombre, Math.round(d * 10) / 10, Math.round(h * 10) / 10, edad]);
    }
  }
  rows[41][4] = Math.round((rows[41][4] as number) * 100); // height typed in centimetres
  rows[150][3] = null; // diameter not recorded
  rows.push([id++, "P3", "roble", 165.0, Math.round(Math.exp(0.65 + 0.55 * Math.log(165)) * 10) / 10, 360]); // giant, on the law
  rows.push([id++, "P7", "haya", 70.0, 8.5, 150]); // broken top: far below the law
  return toCsv(["arbol", "parcela", "especie", "diametro_cm", "altura_m", "edad"], rows);
}

export const DATASETS = [
  { file: "ventas.csv", title: "Ventas de la tienda del reino", make: ventasCsv, description: "Pedidos de 120 días: región, producto, unidades y precio. Contiene faltantes, duplicados, etiquetas inconsistentes y un atípico." },
  { file: "pacientes.csv", title: "Ensayo clínico sintético", make: pacientesCsv, description: "160 pacientes asignados alternadamente a control o tratamiento; presión arterial sistólica antes y después, y un evento binario. Datos inventados con fines educativos." },
  { file: "estudiantes.csv", title: "Rendimiento de estudiantes", make: estudiantesCsv, description: "Horas de estudio, asistencia, nota previa y nota final de 200 estudiantes ficticios." },
  { file: "clientes.csv", title: "Bajas de clientes", make: clientesCsv, description: "1200 clientes ficticios de una compañía de telecomunicaciones: contrato, antigüedad, cuota, llamadas a soporte y si se dieron de baja (clase minoritaria)." },
  { file: "ensayo.csv", title: "Ensayo de un fármaco para el colesterol", make: ensayoCsv, description: "240 pacientes aleatorizados por bloques a fármaco o placebo en tres centros: LDL basal y a las 12 semanas, eventos adversos y abandonos. Con errores de registro. Datos inventados con fines educativos." },
  { file: "sensores.csv", title: "Sensores de temperatura", make: sensoresCsv, description: "Lecturas horarias de dos sensores durante 60 días, con mensajes perdidos, duplicados, desordenados, lecturas «ERR» y anomalías (picos, sensor atascado, valores raros para la hora)." },
  { file: "sensores_etiquetas.csv", title: "Etiquetas de anomalías", make: sensoresEtiquetasCsv, description: "Para cada hora y sensor, si la lectura era una anomalía real. Solo para evaluar detectores." },
  { file: "viviendas.csv", title: "Precios de viviendas", make: viviendasCsv, description: "1500 viviendas ficticias: barrio, superficie, habitaciones, baños, antigüedad, planta, ascensor, distancia al centro y precio (miles de euros). Con faltantes y algunos errores de tecleo." },
  { file: "mensajes.csv", title: "Mensajes de clientes", make: mensajesCsv, description: "900 mensajes ficticios a la tienda del reino, etiquetados como facturación, envío, producto defectuoso o cuenta (clases desequilibradas y un 3 % de etiquetas erróneas)." },
  { file: "demanda.csv", title: "Demanda eléctrica diaria", make: demandaCsv, description: "Demanda de electricidad (MWh) y temperatura media diarias de 2022 a 2024 en una región ficticia: tendencia, ciclo semanal, efecto de la temperatura, festivos y algunos días sin dato." },
  { file: "clima.csv", title: "Clima diario", make: climaCsv, description: "Temperatura y lluvia diarias de un año en una ciudad imaginaria, con estacionalidad." },
] as const;

const cache: Record<string, string> = {};
export function dataset(file: string): string {
  const d = DATASETS.find((x) => x.file === file);
  if (!d) throw new Error(`Dataset desconocido: ${file}`);
  return (cache[file] ??= d.make());
}

/** Parse a simple CSV (no quoted commas) into header + rows of strings. */
export function parseCsv(text: string) {
  const lines = text.trim().split("\n");
  const header = lines[0].split(",");
  const rows = lines.slice(1).map((l) => l.split(","));
  return { header, rows };
}
